  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  line-height: 1.5;
}

.page-wrapper {
  width: 100%;
  max-width: 480px;
}

.form-card {
  background: var(--color-card);
  border-radius: var(--radius-card);
  box-shadow: var(--shadow-card);
  padding: 2.5rem 2rem;
}

.form-header {
  margin-bottom: 2rem;
}

.form-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.form-header p {
  margin-top: 0.4rem;
  font-size: 0.9375rem;
  color: var(--color-muted);
}

/* Form fields */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin-bottom: 1.25rem;
}

label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.required {
  color: var(--color-error);
  font-size: 0.875rem;
}

.optional {
  font-weight: 400;
  font-size: 0.8125rem;
  color: var(--color-muted);
}

input[type="text"],
input[type="email"],
input[type="tel"] {
  width: 100%;
  padding: 0.625rem 0.875rem;
  font-size: 0.9375rem;
  font-family: inherit;
  color: var(--color-text);
  background: var(--color-card);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-field);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition);
}

input::placeholder {
  color: #adb5bd;
}

input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(79, 110, 247, 0.15);
}

input[aria-invalid="true"] {
  border-color: var(--color-error-border);
  background-color: var(--color-error-bg);
}

input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.12);
}

input[aria-invalid="false"] {
  border-color: #6ee7b7;
}

.helper-text {
  font-size: 0.8125rem;
  color: var(--color-helper);
}

.validation-message {
  font-size: 0.8125rem;
  color: var(--color-error);
  min-height: 1.1em;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.validation-message:empty {
  display: none;
}

/* Submit button */
.submit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  margin-top: 0.5rem;
  padding: 0.75rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  font-family: inherit;
  color: #ffffff;
  background: var(--color-primary);
  border: none;
  border-radius: var(--radius-field);
  cursor: pointer;
  transition: background-color var(--transition), transform var(--transition), box-shadow var(--transition);
}

.submit-btn:hover {
  background: var(--color-primary-hover);
  box-shadow: 0 4px 12px rgba(79, 110, 247, 0.35);
}

.submit-btn:active {
  transform: translateY(1px);
  box-shadow: none;
}

.submit-btn:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
}

.submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* Success banner */
.success-banner {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  margin-top: 1.25rem;
  padding: 0.875rem 1rem;
  background: var(--color-success-bg);
  color: var(--color-success);
  font-size: 0.9375rem;
  font-weight: 500;
  border-radius: var(--radius-field);
  border: 1px solid #bbf7d0;
}

.success-banner[hidden] {
  display: none;
}

@media (max-width: 520px) {
  .form-card {
    padding: 2rem 1.25rem;
  }
}
