+const form = document.getElementById('contact-form');
+const successBanner = document.getElementById('success-banner');
+
+const PHONE_REGEX = /^(\+?1[-.\s]?)?(\(?\d{3}\)?[-.\s]?)?\d{3}[-.\s]?\d{4}$/;
+const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+
+function getField(id) {
+  return document.getElementById(id);
+}
+
+function getError(id) {
+  return document.getElementById(`${id}-error`);
+}
+
+function setError(inputId, message) {
+  const input = getField(inputId);
+  const error = getError(inputId);
+  error.textContent = message;
+  input.setAttribute('aria-invalid', 'true');
+}
+
+function clearError(inputId) {
+  const input = getField(inputId);
+  const error = getError(inputId);
+  error.textContent = '';
+  input.setAttribute('aria-invalid', 'false');
+}
+
+function validateFullName() {
+  const value = getField('full-name').value.trim();
+  if (!value) {
+    setError('full-name', 'Full name is required.');
+    return false;
+  }
+  if (value.length < 2) {
+    setError('full-name', 'Please enter your full name.');
+    return false;
+  }
+  clearError('full-name');
+  return true;
+}
+
+function validateEmail() {
+  const value = getField('email').value.trim();
+  if (!value) {
+    setError('email', 'Email address is required.');
+    return false;
+  }
+  if (!EMAIL_REGEX.test(value)) {
+    setError('email', 'Please enter a valid email address.');
+    return false;
+  }
+  clearError('email');
+  return true;
+}
+
+function validatePhone() {
+  const value = getField('phone').value.trim();
+  if (!value) {
+    clearError('phone');
+    return true;
+  }
+  if (!PHONE_REGEX.test(value)) {
+    setError('phone', 'Please enter a valid phone number (e.g. +1 (555) 000-0000).');
+    return false;
+  }
+  clearError('phone');
+  return true;
+}
+
+/* Inline (on-blur) validation */
+getField('full-name').addEventListener('blur', validateFullName);
+getField('email').addEventListener('blur', validateEmail);
+getField('phone').addEventListener('blur', validatePhone);
+
+/* Clear error as user fixes input */
+getField('full-name').addEventListener('input', () => {
+  if (getField('full-name').getAttribute('aria-invalid') === 'true') validateFullName();
+});
+getField('email').addEventListener('input', () => {
+  if (getField('email').getAttribute('aria-invalid') === 'true') validateEmail();
+});
+getField('phone').addEventListener('input', () => {
+  if (getField('phone').getAttribute('aria-invalid') === 'true') validatePhone();
+});
+
+form.addEventListener('submit', (e) => {
+  e.preventDefault();
+
+  const nameOk = validateFullName();
+  const emailOk = validateEmail();
+  const phoneOk = validatePhone();
+
+  if (!nameOk || !emailOk || !phoneOk) {
+    /* Focus the first invalid field */
+    const firstInvalid = form.querySelector('[aria-invalid="true"]');
+    if (firstInvalid) firstInvalid.focus();
+    return;
+  }
+
+  /* Simulate submission */
+  const btn = form.querySelector('.submit-btn');
+  btn.disabled = true;
+  btn.textContent = 'Sending…';
+
+  setTimeout(() => {
+    form.reset();
+    ['full-name', 'email', 'phone'].forEach((id) => {
+      getField(id).removeAttribute('aria-invalid');
+    });
+    btn.disabled = false;
+    btn.textContent = 'Send Message';
+    successBanner.hidden = false;
+    successBanner.focus();
+  }, 800);
+});
+
')

